// Generates src/tokens.css (CSS variables for Tailwind) from src/tokens.ts. Run with `pnpm tokens:build`.
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Tokens } from '../src/tokens.js';

export function buildTokensCss(t: Tokens): string {
  const colors = Object.entries(t.color);
  const block = (mode: 'light' | 'dark') =>
    colors.map(([n, v]) => `  --${n}: ${v[mode]};`).join('\n');
  return [
    '/* Generated by `pnpm tokens:build` from src/tokens.ts. Do not edit. */',
    ':root {',
    block('light'),
    `  --radius: ${t.radius};`,
    `  --spacing: ${t.spacing};`,
    `  --font-sans: ${t.font.sans};`,
    `  --font-mono: ${t.font.mono};`,
    '}',
    '',
    '.dark {',
    block('dark'),
    '}',
    '',
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { tokens } = await import('../src/tokens.js');
  writeFileSync(join(import.meta.dirname, '../src/tokens.css'), buildTokensCss(tokens));
}
